WebLists.wlOnItemClick:
m1.forwardTo({
	screen: "indirect", 
	parameters:{ indirect: this.fields.lmlIndirectLaborID, employee: m1.employee }
});

m1.forwardTo({
	screen: "jobOperation",
	parameters:{
		job: this.fields.lmlJobID, 
		assembly: this.fields.lmlJobAssemblyID, 
		operation: this.fields.lmlJobOperationID, 
		employee: m1.employee
	}
});

m1.forwardTo({
	screen:"jobMaterial",
	parameters:{
		job: this.fields.jmmJobID, 
		assembly: this.fields.jmmJobAssemblyID, 
		material: this.fields.jmmJobMaterialID
	},
	onExit: function () { m1.backTo({ screen: "part" }); }
});

if(this.screen != null)
{
	if(this.screen.id == "part")
	{
		m1.forwardTo({
			screen:"partBin",
			parameters:{
				part: this.fields.imbPartID, 
				revision: this.fields.imbPartRevisionID, 
				warehouse:  this.fields.imbWarehouseID, 
				bin:  this.fields.imbPartBinID
			}
		});
	}
	else
	{
		this.screen.exit();
	}
}

m1.forwardTo({
	screen: "part",
	parameters: {
		part: this.fields.jmmPartID, 
		revision: this.fields.jmmPartRevisionID, 
		employee: m1.employee
	}
});

m1.forwardTo({
	screen: "inventoryCountLine",
	parameters: {
		inventoryCount: this.fields.imqInventoryCountID, 
		line: this.fields.imqInventoryCountLineID
	}
});

m1.forwardTo({
	screen: "jobAssembly",
	parameters: {
		job: this.fields.jmaJobID,
		assembly: this.fields.jmaJobAssemblyID
	}
});

m1.forwardTo({
	screen: "jobMaterial",
	parameters: {
		job: this.fields.jmmJobID,
		assembly: this.fields.jmmJobAssemblyID,
		material: this.fields.jmmJobMaterialID
	}
});

m1.forwardTo({
	screen: "jobMaterial",
	parameters:{
		job: this.fields.jmmJobID, 
		assembly: this.fields.jmmJobAssemblyID, 
		material: this.fields.jmmJobMaterialID
	}
});

m1.forwardTo({
	screen:"part",
	parameters:{
		part: this.fields.imrPartID,
		revision: this.fields.imrPartRevisionID
	}
});

m1.forwardTo({
	screen:"pickListLine",
	parameters: {
		pickList: this.fields.omyPickListSessionID,
		line: this.fields.omyPickListLineID
	}
});

m1.forwardTo({
	screen: "indirect",
	parameters: { indirect: this.fields.lmiIndirectLaborID, employee: m1.employee }
});

m1.forwardTo({
	screen: "jobOperation",
	parameters: {
		job: this.fields.jmoJobID, 
		assembly: this.fields.jmoJobAssemblyID, 
		operation: this.fields.jmoJobOperationID, 
		employee: m1.employee
	}
});
